import re, subprocess, sys, os
env = dict(os.environ); env.pop("NO_COLOR", None); env["TERM"] = "xterm"
args = sys.argv[1:]
p = subprocess.run(["/workspace/executable"] + args, capture_output=True, env=env)
out = p.stdout.decode("utf-8", "replace")
def ann(s):
    # replace ESC[...m with <..>
    return re.sub("\x1b\\[([0-9;]*)m", lambda m: "<"+m.group(1)+">", s)
for line in out.split("\n"):
    print(ann(line))
print("exit=%d" % p.returncode)
if p.stderr:
    print("STDERR:", ann(p.stderr.decode()))

