import json, random, subprocess, sys

def rnd(depth=0):
    r = random.random()
    if depth > 3 or r < 0.35:
        return random.choice([
            random.randint(-1000, 1000), random.random(),
            "".join(random.choice("abAB01_-. \"\\[]$é日") for _ in range(random.randint(0,6))),
            True, False, None, {}, []
        ])
    if r < 0.7:
        keys = set()
        while len(keys) < random.randint(1, 6):
            keys.add("".join(random.choice("abAB01_-.$ é") for _ in range(random.randint(0,4))))
        return {k: rnd(depth+1) for k in keys}
    return [rnd(depth+1) for _ in range(random.randint(0, 5))]

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
bad = 0
for trial in range(300):
    doc = rnd()
    data = json.dumps(doc, ensure_ascii=False).encode()
    n = subprocess.run(["/workspace/executable"], input=data, capture_output=True)
    j = subprocess.run(["/workspace/executable", "-j"], input=data, capture_output=True)
    nl = n.stdout.decode().rstrip("\n").split("\n")
    jl = j.stdout.decode().rstrip("\n").split("\n")
    if len(nl) != len(jl):
        print("LEN MISMATCH trial", trial, len(nl), len(jl)); print(data); bad += 1; continue
    # compare value part
    for a, b in zip(nl, jl):
        # normal: "<path> = <value>;"  json: [[path],value]
        av = a[a.index(" = ")+3:-1]
        arr = json.loads(b)
        bv = json.dumps(arr[1], ensure_ascii=False, separators=(",", ":"))
        # normalize {} [] and numbers/strings loosely: only compare strings & literals
        if av in ("{}", "[]", "true", "false", "null"):
            if av != bv:
                print("VAL MISMATCH", repr(a), repr(b)); bad += 1
        elif av.startswith('"'):
            if av != bv:
                print("STR MISMATCH", repr(a), repr(b), repr(av), repr(bv)); bad += 1
print("done, bad =", bad)
